.fgw{position:relative;width:100%;aspect-ratio:1215/1075;overflow:hidden;-webkit-mask-image:linear-gradient(90deg,transparent 0,#000 7%,#000 94%,transparent 100%),linear-gradient(180deg,transparent 0,#000 7%,#000 95%,transparent 100%);-webkit-mask-composite:source-in;mask-image:linear-gradient(90deg,transparent 0,#000 7%,#000 94%,transparent 100%),linear-gradient(180deg,transparent 0,#000 7%,#000 95%,transparent 100%);mask-composite:intersect}
.fgw>*{position:absolute;left:0;top:0;width:100%;height:100%;display:block}
#fgi{mix-blend-mode:multiply;animation:br 7s ease-in-out infinite;transform-origin:62% 45%}
@keyframes br{50%{transform:scale(1.006)}}
.fgw svg,.fgw canvas{pointer-events:none}
.tl{font:800 19px "Bricolage Grotesque",system-ui,sans-serif;fill:#0b2557;text-anchor:middle;letter-spacing:-.3px}
.ct{font:700 21px "Bricolage Grotesque",system-ui,sans-serif;fill:#161b3f;letter-spacing:-.2px}
.ic{fill:none;stroke:#0b2557;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}
.hl{fill:none;stroke:#2d7cf0;stroke-width:3.5;filter:drop-shadow(0 0 9px #3b8cff);opacity:0}
.spin{fill:none;stroke:#59a2ff;stroke-width:3;stroke-dasharray:18 26;transform-box:fill-box;transform-origin:center;animation:sp 16s linear infinite;opacity:.85}
.spin2{animation-direction:reverse;animation-duration:22s;stroke-dasharray:6 14;opacity:.6}
@keyframes sp{to{transform:rotate(360deg)}}
.sweep{mix-blend-mode:screen;animation:sw 9s ease-in-out infinite}
@keyframes sw{0%{transform:translateX(-560px)}60%,100%{transform:translateX(760px)}}
@media(prefers-reduced-motion:reduce){.fgw *{animation:none!important}}

.hero .sahne.fg{height:auto!important;margin-top:0}
.hero .sahne.fg>*{animation:none}
@media(max-width:900px){.hero .sahne.fg{height:auto!important;margin:18px -8px 0}}

.fgsec{padding:36px 0 8px!important}.fgsec .sahne.fgx{max-width:1040px;margin:0 auto}.fgsec .wrap,.fgsec .w{max-width:1180px;margin:0 auto;padding:0 20px}
.fgsec .wrap.w{width:100%;box-sizing:border-box}.fgsec .sahne.fgx{width:100%;height:auto!important;min-height:0!important;display:block;position:static!important;animation:none}
